/**
 * Creates a compute pass that enforces SDF volume boundary constraints for particle simulations.
 *
 * Applies penalty forces to particles that penetrate the SDF boundary, pushing them
 * back inside the volume and reflecting their velocities.
 *
 * **Use Cases:**
 * - SPH simulations with complex boundaries
 * - Boids flocking within defined volumes
 * - Particle systems constrained to arbitrary shapes
 *
 * @example
 * import { createSDFBoundaryPass } from 'three-blocks';
 *
 * const boundaryPass = createSDFBoundaryPass(
 *   positionsBuffer,
 *   velocitiesBuffer,
 *   sdfGenerator.sdfTexture,
 *   sdfGenerator.inverseBoundsMatrix,
 *   sdfGenerator.boundsMatrix,
 *   {
 *     stiffness: 1000.0,
 *     damping: 0.5,
 *     particleCount: 5000
 *   }
 * );
 *
 * // In animation loop
 * renderer.compute(boundaryPass);
 *
 * @function createSDFBoundaryPass
 * @param {THREE.StorageBufferAttribute} positionsBuffer - Particle positions (vec3)
 * @param {THREE.StorageBufferAttribute} velocitiesBuffer - Particle velocities (vec3)
 * @param {THREE.Storage3DTexture} sdfTexture - SDF 3D texture
 * @param {THREE.Matrix4} inverseBoundsMatrix - World to SDF local space transform
 * @param {THREE.Matrix4} boundsMatrix - SDF local to world space transform
 * @param {Object} options - Configuration options
 * @param {number} options.particleCount - Number of particles
 * @param {number} [options.stiffness=1000.0] - Boundary stiffness coefficient
 * @param {number} [options.damping=0.5] - Velocity damping on collision
 * @param {number} [options.threshold=0.0] - SDF boundary threshold (0 = surface)
 * @param {THREE.Vector3} [options.texelSize] - SDF texel size (1/resolution), auto-computed if not provided
 * @returns {*} TSL compute node
 */
export function createSDFBoundaryPass(positionsBuffer: THREE.StorageBufferAttribute, velocitiesBuffer: THREE.StorageBufferAttribute, sdfTexture: THREE.Storage3DTexture, inverseBoundsMatrix: THREE.Matrix4, boundsMatrix: THREE.Matrix4, options?: {
    particleCount: number;
    stiffness?: number;
    damping?: number;
    threshold?: number;
    texelSize?: THREE.Vector3;
}): any;
/**
 * SDFVolumeConstraint class wrapper for easier integration with simulation systems.
 *
 * @example
 * const constraint = new SDFVolumeConstraint(sdfGenerator, {
 *   stiffness: 1000,
 *   damping: 0.5
 * });
 *
 * // In simulation loop
 * await constraint.apply(renderer, positionsBuffer, velocitiesBuffer, particleCount);
 */
export class SDFVolumeConstraint {
    /**
     * @param {ComputeSDFGenerator} sdfGenerator - SDF generator instance
     * @param {Object} [options] - Configuration options
     * @param {number} [options.stiffness=1000.0] - Boundary stiffness
     * @param {number} [options.damping=0.5] - Velocity damping
     * @param {number} [options.threshold=0.0] - SDF boundary threshold
     */
    constructor(sdfGenerator: ComputeSDFGenerator, options?: {
        stiffness?: number;
        damping?: number;
        threshold?: number;
    });
    /** @type {ComputeSDFGenerator} */
    sdfGenerator: ComputeSDFGenerator;
    /** @type {number} */
    stiffness: number;
    /** @type {number} */
    damping: number;
    /** @type {number} */
    threshold: number;
    /** @private */
    private _computeNode;
    /** @private */
    private _cachedParticleCount;
    /** @private */
    private _cachedSDFTexture;
    /** @private */
    private _cachedPositionsBuffer;
    /** @private */
    private _cachedVelocitiesBuffer;
    /**
     * Applies the SDF boundary constraint to particle buffers.
     *
     * @param {THREE.WebGPURenderer} renderer - WebGPU renderer
     * @param {THREE.StorageBufferAttribute} positionsBuffer - Particle positions
     * @param {THREE.StorageBufferAttribute} velocitiesBuffer - Particle velocities
     * @param {number} particleCount - Number of particles
     * @returns {Promise<void>}
     */
    apply(renderer: THREE.WebGPURenderer, positionsBuffer: THREE.StorageBufferAttribute, velocitiesBuffer: THREE.StorageBufferAttribute, particleCount: number): Promise<void>;
    /**
     * Updates the SDF generator (useful when SDF is regenerated).
     *
     * @param {ComputeSDFGenerator} sdfGenerator - New SDF generator
     */
    updateSDF(sdfGenerator: ComputeSDFGenerator): void;
}
